        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MEMBERS_ADDED_IN_YEAR end) as MEMBERS_ADDED_IN_YEAR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MEMBERS_DELETED_IN_YEAR end) as MEMBERS_DELETED_IN_YEAR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MEMBER_AGE_BAND end) as MEMBER_AGE_BAND,
        max(case when SOURCE_RUN = 'opus_health_v2' then ISSUANCE_WITH_MEMBER_DATA_INDICATOR end) as ISSUANCE_WITH_MEMBER_DATA_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then GROUP_NUMBER end) as GROUP_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_v2' then GROUP_CONTRACT_PORTAL_LOGIN_IDENTIFIER end) as GROUP_CONTRACT_PORTAL_LOGIN_IDENTIFIER,
        max(case when SOURCE_RUN = 'opus_health_v2' then GROUP_SCHEME_CODE end) as GROUP_SCHEME_CODE,
        max(case when SOURCE_RUN = 'opus_health_v2' then MASTER_CONTRACT_CONFIGURATION_ACTIVE_INDICATOR end) as MASTER_CONTRACT_CONFIGURATION_ACTIVE_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then MEMBER_BULK_LOADER_ENABLED_INDICATOR end) as MEMBER_BULK_LOADER_ENABLED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then MEMBER_LEVEL_DATA_CAPTURED_INDICATOR end) as MEMBER_LEVEL_DATA_CAPTURED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then MEMBER_BULK_LOADER_FORMAT end) as MEMBER_BULK_LOADER_FORMAT,
        max(case when SOURCE_RUN = 'opus_health_v2' then SUM_INSURED_RATING_FACTOR_INDICATOR end) as SUM_INSURED_RATING_FACTOR_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then CORONA_COVER_VARIANT_ENABLED_INDICATOR end) as CORONA_COVER_VARIANT_ENABLED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then MOBILE_CAPTURE_BYPASS_ALLOWED_INDICATOR end) as MOBILE_CAPTURE_BYPASS_ALLOWED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then UNDERWRITING_REMARKS_CAPTURED_INDICATOR end) as UNDERWRITING_REMARKS_CAPTURED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then REMAPPED_MASTER_POLICY_REFERENCE end) as REMAPPED_MASTER_POLICY_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_v2' then CKYC_CAPTURE_REQUIRED_INDICATOR end) as CKYC_CAPTURE_REQUIRED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then FAMILY_FLOATER_DETAILS_CAPTURED_INDICATOR end) as FAMILY_FLOATER_DETAILS_CAPTURED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then GROUP_COVER_DAY_COUNT_MULTIPLIER end) as GROUP_COVER_DAY_COUNT_MULTIPLIER,
        max(case when SOURCE_RUN = 'opus_health_v2' then GROUP_COVER_DAY_COUNT_YEARS_MULTIPLIER end) as GROUP_COVER_DAY_COUNT_YEARS_MULTIPLIER,
        max(case when SOURCE_RUN = 'opus_health_v2' then MEMBER_BMI_CALCULATION_INDICATOR end) as MEMBER_BMI_CALCULATION_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then HEALTH_ASSESSMENT_TOOL_REFERRAL_INDICATOR end) as HEALTH_ASSESSMENT_TOOL_REFERRAL_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then MEMBER_DOB_RATING_AGE_VALIDATION_INDICATOR end) as MEMBER_DOB_RATING_AGE_VALIDATION_INDICATOR,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then FAMILY_DEFINITION_DESCRIPTION end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then FAMILY_DEFINITION_DESCRIPTION end)) as FAMILY_DEFINITION_DESCRIPTION,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then ELIGIBLE_RELATIONSHIP_SET end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then ELIGIBLE_RELATIONSHIP_SET end)) as ELIGIBLE_RELATIONSHIP_SET,
        max(case when SOURCE_RUN = 'opus_health_v2' then PRIMARY_MEMBER_COUNT end) as PRIMARY_MEMBER_COUNT,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then DEPENDENT_MEMBER_COUNT end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then DEPENDENT_MEMBER_COUNT end)) as DEPENDENT_MEMBER_COUNT,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then MAXIMUM_MEMBERS_PER_FAMILY end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then MAXIMUM_MEMBERS_PER_FAMILY end)) as MAXIMUM_MEMBERS_PER_FAMILY,
        max(case when SOURCE_RUN = 'opus_health_v2' then PARENTAL_SUM_INSURED_RESTRICTION end) as PARENTAL_SUM_INSURED_RESTRICTION,
        max(case when SOURCE_RUN = 'opus_health_delta3' then FAMILY_INCLUSION_DEFINITION end) as FAMILY_INCLUSION_DEFINITION,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK
),

hashed as (
    select
        *,
        case when EMPLOYER_CONTRIBUTION_AMOUNT is not null or EXPIRING_MEMBER_COUNT is not null or FINAL_MEMBER_COUNT_AT_EXPIRY is not null or MEMBERS_ADDED_IN_YEAR is not null or MEMBERS_DELETED_IN_YEAR is not null or MEMBER_AGE_BAND is not null or ISSUANCE_WITH_MEMBER_DATA_INDICATOR is not null or GROUP_NUMBER is not null or GROUP_CONTRACT_PORTAL_LOGIN_IDENTIFIER is not null or GROUP_SCHEME_CODE is not null or MASTER_CONTRACT_CONFIGURATION_ACTIVE_INDICATOR is not null or MEMBER_BULK_LOADER_ENABLED_INDICATOR is not null or MEMBER_LEVEL_DATA_CAPTURED_INDICATOR is not null or MEMBER_BULK_LOADER_FORMAT is not null or SUM_INSURED_RATING_FACTOR_INDICATOR is not null or CORONA_COVER_VARIANT_ENABLED_INDICATOR is not null or MOBILE_CAPTURE_BYPASS_ALLOWED_INDICATOR is not null or UNDERWRITING_REMARKS_CAPTURED_INDICATOR is not null or REMAPPED_MASTER_POLICY_REFERENCE is not null or CKYC_CAPTURE_REQUIRED_INDICATOR is not null or FAMILY_FLOATER_DETAILS_CAPTURED_INDICATOR is not null or GROUP_COVER_DAY_COUNT_MULTIPLIER is not null or GROUP_COVER_DAY_COUNT_YEARS_MULTIPLIER is not null or MEMBER_BMI_CALCULATION_INDICATOR is not null or HEALTH_ASSESSMENT_TOOL_REFERRAL_INDICATOR is not null or MEMBER_DOB_RATING_AGE_VALIDATION_INDICATOR is not null or FAMILY_DEFINITION_DESCRIPTION is not null or ELIGIBLE_RELATIONSHIP_SET is not null or PRIMARY_MEMBER_COUNT is not null or DEPENDENT_MEMBER_COUNT is not null or MAXIMUM_MEMBERS_PER_FAMILY is not null or PARENTAL_SUM_INSURED_RESTRICTION is not null or FAMILY_INCLUSION_DEFINITION is not null
                     then md5(upper(coalesce(cast(EMPLOYER_CONTRIBUTION_AMOUNT as varchar), '') || '|' || coalesce(cast(EXPIRING_MEMBER_COUNT as varchar), '') || '|' || coalesce(cast(FINAL_MEMBER_COUNT_AT_EXPIRY as varchar), '') || '|' || coalesce(cast(MEMBERS_ADDED_IN_YEAR as varchar), '') || '|' || coalesce(cast(MEMBERS_DELETED_IN_YEAR as varchar), '') || '|' || coalesce(cast(MEMBER_AGE_BAND as varchar), '') || '|' || coalesce(cast(ISSUANCE_WITH_MEMBER_DATA_INDICATOR as varchar), '') || '|' || coalesce(cast(GROUP_NUMBER as varchar), '') || '|' || coalesce(cast(GROUP_CONTRACT_PORTAL_LOGIN_IDENTIFIER as varchar), '') || '|' || coalesce(cast(GROUP_SCHEME_CODE as varchar), '') || '|' || coalesce(cast(MASTER_CONTRACT_CONFIGURATION_ACTIVE_INDICATOR as varchar), '') || '|' || coalesce(cast(MEMBER_BULK_LOADER_ENABLED_INDICATOR as varchar), '') || '|' || coalesce(cast(MEMBER_LEVEL_DATA_CAPTURED_INDICATOR as varchar), '') || '|' || coalesce(cast(MEMBER_BULK_LOADER_FORMAT as varchar), '') || '|' || coalesce(cast(SUM_INSURED_RATING_FACTOR_INDICATOR as varchar), '') || '|' || coalesce(cast(CORONA_COVER_VARIANT_ENABLED_INDICATOR as varchar), '') || '|' || coalesce(cast(MOBILE_CAPTURE_BYPASS_ALLOWED_INDICATOR as varchar), '') || '|' || coalesce(cast(UNDERWRITING_REMARKS_CAPTURED_INDICATOR as varchar), '') || '|' || coalesce(cast(REMAPPED_MASTER_POLICY_REFERENCE as varchar), '') || '|' || coalesce(cast(CKYC_CAPTURE_REQUIRED_INDICATOR as varchar), '') || '|' || coalesce(cast(FAMILY_FLOATER_DETAILS_CAPTURED_INDICATOR as varchar), '') || '|' || coalesce(cast(GROUP_COVER_DAY_COUNT_MULTIPLIER as varchar), '') || '|' || coalesce(cast(GROUP_COVER_DAY_COUNT_YEARS_MULTIPLIER as varchar), '') || '|' || coalesce(cast(MEMBER_BMI_CALCULATION_INDICATOR as varchar), '') || '|' || coalesce(cast(HEALTH_ASSESSMENT_TOOL_REFERRAL_INDICATOR as varchar), '') || '|' || coalesce(cast(MEMBER_DOB_RATING_AGE_VALIDATION_INDICATOR as varchar), '') || '|' || coalesce(cast(FAMILY_DEFINITION_DESCRIPTION as varchar), '') || '|' || coalesce(cast(ELIGIBLE_RELATIONSHIP_SET as varchar), '') || '|' || coalesce(cast(PRIMARY_MEMBER_COUNT as varchar), '') || '|' || coalesce(cast(DEPENDENT_MEMBER_COUNT as varchar), '') || '|' || coalesce(cast(MAXIMUM_MEMBERS_PER_FAMILY as varchar), '') || '|' || coalesce(cast(PARENTAL_SUM_INSURED_RESTRICTION as varchar), '') || '|' || coalesce(cast(FAMILY_INCLUSION_DEFINITION as varchar), '')))
                end as SAT_POLICY_GROUP_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_GROUP_HASHDIFF is not null
